function Modal({title,close,children}:any){useEffect(()=>{const prev=document.body.style.overflow;const prior=document.activeElement as HTMLElement;document.body.style.overflow='hidden';const trap=(e:KeyboardEvent)=>{if(e.key!=='Tab')return;const elements=Array.from(document.querySelectorAll<HTMLElement>('.modal button:not([disabled]),.modal input:not([disabled]),.modal select:not([disabled]),.modal textarea,.modal a[href]'));const first=elements[0],last=elements[elements.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}};document.addEventListener('keydown',trap);return()=>{document.body.style.overflow=prev;document.removeEventListener('keydown',trap);prior?.focus()}},[]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><section className="modal" role="dialog" aria-modal="true" aria-label={title}><div className="modal-heading"><h2>{title}</h2><button autoFocus className="icon-button" aria-label="Close dialog" onClick={close}><X size={20}/></button></div><div className="modal-body">{children}</div></section></div>}
const chartPalette=['#4f46e5','#06b6d4','#10b981','#f59e0b','#ec4899','#8b5cf6','#ef4444','#84cc16'];
function ChartCard({title,subtitle,type,children}:any){return <section className="card chart-card"><div className="chart-heading"><div><h2>{title}</h2><p>{subtitle}</p></div><Badge>{type}</Badge></div>{children}</section>}
function LineMetricChart({data}:any){const width=620,height=220,pad=28,max=Math.max(1,...data.flatMap((d:any)=>[d.requests,d.errors]));const points=(key:string)=>data.map((d:any,i:number)=>`${pad+i*(width-pad*2)/Math.max(data.length-1,1)},${height-pad-d[key]*(height-pad*2)/max}`).join(' ');return <div className="chart-body line-chart"><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label="API traffic line chart"><defs><linearGradient id="lineFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#4f46e5" stopOpacity=".24"/><stop offset="1" stopColor="#4f46e5" stopOpacity="0"/></linearGradient></defs>{[0,1,2,3,4].map(i=><line key={i} x1={pad} x2={width-pad} y1={pad+i*(height-pad*2)/4} y2={pad+i*(height-pad*2)/4} className="chart-gridline"/>)}<polygon points={`${pad},${height-pad} ${points('requests')} ${width-pad},${height-pad}`} fill="url(#lineFill)"/><polyline points={points('requests')} fill="none" stroke="#4f46e5" strokeWidth="3"/><polyline points={points('errors')} fill="none" stroke="#f43f5e" strokeWidth="2" strokeDasharray="5 5"/>{data.map((d:any,i:number)=><circle key={i} cx={pad+i*(width-pad*2)/Math.max(data.length-1,1)} cy={height-pad-d.requests*(height-pad*2)/max} r="3" fill="#4f46e5"><title>{d.label}: {d.requests} requests, {d.errors} rejected</title></circle>)}</svg><div className="chart-legend"><span><i style={{background:'#4f46e5'}}/>Requests</span><span><i style={{background:'#f43f5e'}}/>Rejected</span><b>Peak {max}</b></div></div>}
function DonutChart({data,center}:any){const total=Math.max(1,data.reduce((n:number,x:any)=>n+x.value,0));let at=0;const gradient=data.map((x:any,i:number)=>{const start=at;at+=x.value/total*100;return `${chartPalette[i%chartPalette.length]} ${start}% ${at}%`}).join(',');return <div className="chart-body donut-layout"><div className="donut" style={{background:`conic-gradient(${gradient||'#e5e7eb 0 100%'})`}}><div><b>{center}</b><small>Total</small></div></div><div className="donut-legend">{data.map((x:any,i:number)=><span key={x.id}><i style={{background:chartPalette[i%chartPalette.length]}}/><b>{x.id}</b><small>{x.value} · {Math.round(x.value/total*100)}%</small></span>)}</div></div>}
function BarMetricChart({data}:any){const max=Math.max(1,...data.map((x:any)=>x.value));return <div className="chart-body bar-chart">{data.map((x:any,i:number)=><div key={x.id}><span>{x.id}</span><div><i style={{width:(x.value/max*100)+'%',background:chartPalette[i%chartPalette.length]}}><em>{x.value}</em></i></div><small>{x.latency} ms avg</small></div>)}</div>}
function HeatmapChart({data}:any){const max=Math.max(1,...data.flatMap((x:any)=>[x.value-x.errors,x.errors]));return <div className="chart-body heatmap"><div className="heatmap-head"><span>Protocol</span><b>Allowed</b><b>Rejected</b></div>{data.map((x:any)=><div key={x.id}><span>{x.id}</span>{[x.value-x.errors,x.errors].map((v:number,i:number)=><b key={i} style={{background:`rgba(${i?'244,63,94':'79,70,229'},${.12+.8*v/max})`}}>{v}</b>)}</div>)}<p>Darker cells indicate a larger share of observed traffic.</p></div>}
function BumpMetricChart({data}:any){const keys=['rest','scim','soap','graphql','oauth','portal'],width=620,height=210,pad=28;const ranks=data.map((d:any)=>[...keys].sort((a,b)=>(d.byProtocol?.[b]||0)-(d.byProtocol?.[a]||0)));return <div className="chart-body bump-chart"><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label="Protocol traffic ranking chart">{keys.map((key,k)=>{const pts=data.map((d:any,i:number)=>`${pad+i*(width-pad*2)/Math.max(data.length-1,1)},${pad+ranks[i].indexOf(key)*(height-pad*2)/(keys.length-1)}`).join(' ');return <g key={key}><polyline points={pts} fill="none" stroke={chartPalette[k]} strokeWidth="3" opacity=".82"/><text x={width-pad+3} y={pad+ranks[ranks.length-1]?.indexOf(key)*(height-pad*2)/(keys.length-1)+4} fill={chartPalette[k]}>{key}</text></g>})}</svg></div>}
function CalendarMetricChart({data}:any){const max=Math.max(1,...data.map((x:any)=>x.value));return <div className="chart-body calendar-chart"><div>{data.map((x:any)=><span key={x.date} title={`${x.date}: ${x.value} requests`} style={{background:`rgba(16,185,129,${.08+.88*x.value/max})`}}><small>{new Date(x.date+'T00:00:00').getDate()}</small></span>)}</div><p>Each cell is one day · darker green means more API activity.</p></div>}
function GeoMetricChart({data}:any){const max=Math.max(1,...data.map((x:any)=>x.value));return <div className="chart-body geo-chart"><div className="world-orbit"><Globe2 size={92}/>{data.slice(0,8).map((x:any,i:number)=><i key={x.id} style={{'--i':i,'--size':8+x.value/max*10} as any}><title>{x.id}: {x.value}</title></i>)}</div><div className="geo-list">{data.slice(0,8).map((x:any,i:number)=><span key={x.id}><i style={{background:chartPalette[i%chartPalette.length]}}/>{x.id}<b>{x.value}</b></span>)}</div></div>}
function SunburstMetricChart({data}:any){const total=Math.max(1,data.reduce((n:number,x:any)=>n+x.value,0));let at=0;const gradient=data.map((x:any,i:number)=>{const start=at;at+=x.value/total*100;return `${chartPalette[i%chartPalette.length]} ${start}% ${at}%`}).join(',');return <div className="chart-body sunburst-layout"><div className="sunburst" style={{background:`conic-gradient(${gradient})`}}><div><span/><b>{data.length}</b><small>departments</small></div></div><div className="sunburst-list">{data.slice(0,7).map((x:any,i:number)=><span key={x.id}><i style={{background:chartPalette[i%chartPalette.length]}}/>{x.id}<b>{x.value}</b></span>)}</div></div>}
function RiskBars({data}:any){const max=Math.max(1,...data.map((x:any)=>x.value));return <div className="chart-body risk-bars">{data.map((x:any,i:number)=><div key={x.id}><span><b>{x.id}</b><strong>{x.value}</strong></span><i><em style={{width:(x.value/max*100)+'%',background:chartPalette[(i+3)%chartPalette.length]}}/></i></div>)}</div>}
function RequestTable({rows,inspect}:any){return rows.length?<div className="table-wrap"><table><thead><tr><th>Request</th><th>Protocol</th><th>Outcome</th><th>Duration</th><th>Time</th><th/></tr></thead><tbody>{rows.map((r:any)=><tr key={r.id}><td><div className="request-path"><code className="method">{r.method}</code><code>{r.path}</code></div><small>{r.actor||'Anonymous'}</small></td><td><Badge>{r.protocol}</Badge></td><td><Badge tone={r.status<400?'green':'red'}>{r.status} {r.status<400?'Success':'Rejected'}</Badge></td><td className="mono">{Number(r.durationMs||0).toFixed(1)} ms</td><td><small>{date(r.timestamp)}</small></td><td><button className="icon-button" aria-label="Inspect request" onClick={()=>inspect(r)}><ArrowUpRight size={17}/></button></td></tr>)}</tbody></table></div>:<Empty/>}
function RequestDetail({record:r}:any){const [tab,setTab]=useState('Summary');return <><div className="tabs">{['Summary','Authentication','Audit records','Raw metadata'].map(t=><button key={t} className={t===tab?'active':''} onClick={()=>setTab(t)}>{t}</button>)}</div>{tab==='Summary'?<><div className="request-detail-title"><Badge tone={r.status<400?'green':'red'}>{r.status}</Badge><code>{r.method} {r.path}</code></div><dl>{Object.entries({Protocol:r.protocol,Duration:Number(r.durationMs).toFixed(2)+' ms',Timestamp:date(r.timestamp),Actor:r.actor||'Anonymous','Policy decision':r.decision,'Correlation ID':r.correlationId,'Related identity':r.userId||'—',Error:r.error||'None'}).map(([k,v])=><React.Fragment key={k}><dt>{k}</dt><dd>{String(v??'—')}</dd></React.Fragment>)}</dl><p className="muted">Total duration is measured. Internal stage timings and request/response bodies are not retained.</p></>:<pre>{pretty(tab==='Authentication'?{authentication:r.authentication,actor:r.actor,decision:r.decision,error:r.error}:tab==='Audit records'?r.audit||r.auditRecords||[]:r)}</pre>}</>}
function PaymentTable({rows,me,canApprove,inspect,approve,reject}:any){if(!rows?.length)return <Empty text="No payment requests yet."/>;return <div className="payment-list">{rows.map((p:any)=>{const assigned=canApprove&&p.status==='Pending'&&p.assignedApproverId===me.id&&p.createdBy!==me.id;return <article className="payment-row" key={p.id}><span className={'payment-icon '+String(p.status).toLowerCase()}><CircleDollarSign size={19}/></span><div className="payment-main"><div><b>{p.reference}</b><Badge tone={p.status==='Approved'?'green':p.status==='Rejected'?'red':'amber'}>{p.status}</Badge></div><small>{p.fromCustomer||p.fromAccountNumber||p.fromAccountId} → {p.toCustomer||p.toAccountNumber||p.toAccountId}</small><span>Created by {p.createdByName||p.createdBy} · {date(p.createdAt)}</span></div><div className="payment-approval"><small>{p.approvalTier||'Standard review'}</small><b>{p.assignedApproverName||'Unassigned'}</b><span>{p.assignedApproverId===me.id&&p.status==='Pending'?'Assigned to you':'Assigned approver'}</span></div><strong className="payment-amount">{new Intl.NumberFormat('en-US',{style:'currency',currency:p.currency||'USD'}).format(Number(p.amount))}</strong><div className="payment-actions"><button className="text-button" onClick={()=>inspect(p)}>Timeline</button>{assigned&&<><button className="button small danger" onClick={()=>reject(p)}>Reject</button><button className="primary small" onClick={()=>approve(p)}>Approve</button></>}</div></article>})}</div>}
function RejectionForm({payment,save}:any){const [reason,setReason]=useState('');return <form onSubmit={e=>{e.preventDefault();save(reason)}}><div className="notice"><CircleDollarSign size={20}/><div><b>{payment.reference}</b><p>{payment.currency} {payment.amount} · assigned to {payment.assignedApproverName}</p></div></div><label>Reason for rejection<textarea required minLength={3} maxLength={300} rows={4} value={reason} onChange={e=>setReason(e.target.value)} placeholder="Explain why this payment cannot be approved."/></label><p className="muted">The payment will remain recorded with its decision history. No account balances will change.</p><div className="form-actions"><button className="primary" disabled={reason.trim().length<3}>Record rejection</button></div></form>}
function GenericTable({rows,inspect,approve}:any){if(!rows?.length)return <Empty/>;const keys=Object.keys(rows[0]).filter(k=>!['createdBy','approvedBy'].includes(k)).slice(0,7);return <div className="table-wrap"><table><thead><tr>{keys.map(k=><th key={k}>{k.replace(/([A-Z])/g,' $1')}</th>)}<th/></tr></thead><tbody>{rows.map((r:any,i:number)=><tr key={r.id||i}>{keys.map(k=><td key={k}>{typeof r[k]==='object'?JSON.stringify(r[k]):String(r[k]??'—')}</td>)}<td><div className="row-actions"><button className="text-button" onClick={()=>inspect(r)}>Details</button>{approve&&<button className="button small" disabled={String(r.status).toLowerCase()!=='pending'} onClick={()=>approve(r)}>Approve</button>}</div></td></tr>)}</tbody></table></div>}
function RoleForm({role,permissions,busy,save,remove}:any){const [v,setV]=useState({...role});return <form onSubmit={e=>{e.preventDefault();save(v)}}><label>Role name<input required value={v.name||''} onChange={e=>setV({...v,name:e.target.value})}/></label><label>Description<textarea rows={2} value={v.description||''} onChange={e=>setV({...v,description:e.target.value})}/></label><h3>Permissions</h3><div className="checkbox-grid permission-checks">{permissions.map((p:any)=><label key={p.id}><input type="checkbox" checked={v.permissions?.includes(p.id)||false} onChange={e=>setV({...v,permissions:e.target.checked?[...(v.permissions||[]),p.id]:v.permissions.filter((x:string)=>x!==p.id)})}/><span><b>{p.name}</b><code>{p.id}</code></span></label>)}</div><div className="form-actions">{remove&&<button type="button" className="text-button danger" onClick={remove}>Delete role</button>}<button className="primary" disabled={busy||!v.name}><ShieldCheck size={16}/>Save role</button></div></form>}
function GroupForm({group,roles,users,busy,save,remove}:any){const [v,setV]=useState({...group});return <form onSubmit={e=>{e.preventDefault();save(v)}}><label>Group name<input required value={v.displayName||''} onChange={e=>setV({...v,displayName:e.target.value})}/></label><h3>Assigned roles</h3><div className="checkbox-grid">{roles.map((r:any)=><label key={r.id}><input type="checkbox" checked={v.roles?.includes(r.id)||false} onChange={e=>setV({...v,roles:e.target.checked?[...(v.roles||[]),r.id]:v.roles.filter((x:string)=>x!==r.id)})}/>{r.name}</label>)}</div><h3>Employee members</h3><div className="member-picker">{users.map((u:any)=><label key={u.id}><input type="checkbox" checked={v.members?.includes(u.id)||false} onChange={e=>setV({...v,members:e.target.checked?[...(v.members||[]),u.id]:v.members.filter((x:string)=>x!==u.id)})}/><span className="avatar">{u.displayName.slice(0,2).toUpperCase()}</span><span><b>{u.displayName}</b><small>{u.department} · {u.jobTitle}</small></span></label>)}</div><div className="form-actions">{remove&&<button type="button" className="text-button danger" onClick={remove}>Delete group</button>}<button className="primary" disabled={busy||!v.displayName}><Users size={16}/>Save group</button></div></form>}
function PermissionForm({busy,save}:any){const [v,setV]=useState({id:'',name:'',description:''});return <form onSubmit={e=>{e.preventDefault();save(v)}}><div className="notice"><Shield size={20}/><p>Custom permissions become available to custom roles immediately. Application code must still enforce the permission at the relevant operation.</p></div><label>Permission key<input required pattern="[A-Z][A-Z0-9_]{2,63}" value={v.id} onChange={e=>setV({...v,id:e.target.value.toUpperCase().replace(/[^A-Z0-9_]/g,'')})} placeholder="REPORT_EXPORT"/><small>Uppercase letters, numbers and underscores.</small></label><label>Display name<input required value={v.name} onChange={e=>setV({...v,name:e.target.value})} placeholder="Export reports"/></label><label>Description<textarea rows={3} value={v.description} onChange={e=>setV({...v,description:e.target.value})}/></label><div className="form-actions"><button className="primary" disabled={busy||!v.id||!v.name}><Plus size={16}/>Create permission</button></div></form>}
function UserForm({user,roles,groups,busy,save,reset,remove,canStatus,canReset}:any){const [v,setV]=useState({...user}),[password,setPassword]=useState('');const set=(k:string,x:any)=>setV({...v,[k]:x});return <form onSubmit={e=>{e.preventDefault();const fields=['username','displayName','email','department','jobTitle','country','city','password','active','locked','roles','groups'];save(Object.fromEntries(fields.filter(k=>v[k]!==undefined&&(!user.id||JSON.stringify(v[k])!==JSON.stringify(user[k]))).map(k=>[k,v[k]])))}}><div className="form-grid">{[['username','Username'],['displayName','Full name'],['email','Email address'],['department','Department'],['jobTitle','Job title'],['country','Country'],['city','City']].map(([k,label])=><label key={k}>{label}<input required={['username','displayName','email'].includes(k)} type={k==='email'?'email':'text'} value={v[k]||''} onChange={e=>set(k,e.target.value)}/></label>)}{!user.id&&<label>Initial password<input required minLength={12} type="password" value={v.password||''} onChange={e=>set('password',e.target.value)}/></label>}</div><div className="checkbox-row"><label><input type="checkbox" disabled={!canStatus} checked={v.active} onChange={e=>set('active',e.target.checked)}/>Account enabled</label><label><input type="checkbox" disabled={!canStatus} checked={v.locked||false} onChange={e=>set('locked',e.target.checked)}/>Account locked</label></div><h3>Assigned roles</h3><div className="checkbox-grid">{roles.map((r:any)=><label key={r.id}><input type="checkbox" checked={v.roles?.includes(r.id)||false} onChange={e=>set('roles',e.target.checked?[...(v.roles||[]),r.id]:v.roles.filter((x:string)=>x!==r.id))}/>{r.name}</label>)}</div><h3>Group memberships</h3><div className="checkbox-grid">{groups.map((g:any)=><label key={g.id}><input type="checkbox" checked={v.groups?.includes(g.id)||false} onChange={e=>set('groups',e.target.checked?[...(v.groups||[]),g.id]:v.groups.filter((x:string)=>x!==g.id))}/>{g.displayName}</label>)}</div><div className="form-actions">{user.id&&canStatus&&<button type="button" className="text-button danger" onClick={remove}>Delete identity</button>}<button className="primary" disabled={busy}><Check size={16}/>Save identity</button></div>{user.id&&canReset&&<div className="reset-box"><h3>Administrative password reset</h3><label>New password<input type="password" minLength={12} value={password} onChange={e=>setPassword(e.target.value)}/></label><button type="button" className="button" disabled={password.length<12||busy} onClick={async()=>{await reset(password);setPassword('')}}>Reset password</button></div>}</form>}
function SsoRegistry({providers,edit,create}:any){return <section className="card sso-registry"><div className="section-heading"><div><h2>Upstream employee SSO</h2><p>Connect Microsoft Entra ID, Okta, or another standards-based identity provider.</p></div><button className="primary" onClick={create}><Plus size={15}/>Add provider</button></div><div className="sso-provider-grid">{providers.map((p:any)=><button key={p.id} onClick={()=>edit(p)}><span className={'sso-logo '+p.preset}>{p.preset==='entra'?'M':p.preset==='okta'?'O':p.type==='saml'?'S':'ID'}</span><div><b>{p.name}</b><small>{p.preset==='entra'?'Microsoft Entra ID':p.preset==='okta'?'Okta':p.type==='saml'?'SAML 2.0 metadata':'Generic OpenID Connect'}</small><span>{p.enabled?'Enabled':'Disabled'} · {p.type==='oidc'?'Authorization Code + PKCE':'Deployment adapter required'}</span></div><Badge tone={p.enabled&&p.type==='oidc'?'green':p.enabled?'amber':''}>{p.type.toUpperCase()}</Badge></button>)}{!providers.length&&<button className="sso-empty" onClick={create}><Plus size={20}/><div><b>Connect your first identity provider</b><small>Use an Entra, Okta, generic OIDC or SAML configuration.</small></div></button>}</div><div className="sso-note"><ShieldCheck size={18}/><span><b>OIDC is operational.</b> It uses Authorization Code, S256 PKCE, state, nonce, issuer, audience, expiry and RS256 signature validation. SAML configuration generates SP metadata; signed assertion processing remains gated until a deployment SAML verification adapter is installed.</span></div></section>}
function SsoProviderForm({provider,roles,busy,save,remove}:any){const [v,setV]=useState({...provider,allowedDomains:(provider.allowedDomains||[]).join(', '),claimMapping:{...ssoClaimDefaults,...(provider.claimMapping||{})},correlationAttribute:provider.correlationAttribute||'email'});const set=(key:string,value:any)=>setV({...v,[key]:value});return <form onSubmit={e=>{e.preventDefault();save({...v,allowedDomains:String(v.allowedDomains||'').split(',').map((x:string)=>x.trim()).filter(Boolean)})}}><div className="form-grid"><label>Protocol<select value={v.type||'oidc'} onChange={e=>set('type',e.target.value)}><option value="oidc">OpenID Connect</option><option value="saml">SAML 2.0 setup kit</option></select></label>{v.type==='oidc'&&<label>Provider preset<select value={v.preset||'generic'} onChange={e=>set('preset',e.target.value)}><option value="entra">Microsoft Entra ID</option><option value="okta">Okta</option><option value="generic">Generic OIDC</option></select></label>}<label>Provider name<input required value={v.name||''} onChange={e=>set('name',e.target.value)} placeholder="Corporate SSO"/></label>{v.type==='oidc'&&v.preset==='entra'&&<label>Entra tenant ID<input required value={v.tenantId||''} onChange={e=>set('tenantId',e.target.value)} placeholder="Tenant GUID or domain"/></label>}{v.type==='oidc'&&v.preset!=='entra'&&<label>Issuer URL<input required type="url" value={v.issuer||''} onChange={e=>set('issuer',e.target.value)} placeholder="https://id.example.com/oauth2/default"/></label>}{v.type==='oidc'&&<><label>Client ID<input required value={v.clientId||''} onChange={e=>set('clientId',e.target.value)}/></label><label>Client secret<input required={!provider.id} type="password" value={v.clientSecret||''} onChange={e=>set('clientSecret',e.target.value)} placeholder={provider.id?'Leave blank to keep existing secret':''}/></label></>}{v.type==='saml'&&<><label>IdP entity ID<input required value={v.entityId||''} onChange={e=>set('entityId',e.target.value)}/></label><label>IdP SSO URL<input required type="url" value={v.ssoUrl||''} onChange={e=>set('ssoUrl',e.target.value)}/></label><label className="span-two">IdP signing certificate<textarea required={!provider.id} rows={5} value={v.signingCertificate||''} onChange={e=>set('signingCertificate',e.target.value)} placeholder="-----BEGIN CERTIFICATE-----"/></label></>}</div><label>Allowed email domains<input value={v.allowedDomains||''} onChange={e=>set('allowedDomains',e.target.value)} placeholder="example.com, subsidiary.example"/><small>Leave blank to allow all domains returned by the provider.</small></label>{v.type==='oidc'&&<section className="claim-mapping"><div><h3>Authentication attribute mapping</h3><p>Map trusted IdP claims to employee identity fields. Dot paths such as <code>extension.department</code> are supported.</p></div><label>Account correlation<select value={v.correlationAttribute||'email'} onChange={e=>set('correlationAttribute',e.target.value)}><option value="email">Match existing employee by email</option><option value="username">Match existing employee by username</option></select></label><div className="mapping-grid">{Object.entries(ssoClaimDefaults).map(([field,fallback])=><label key={field}><span>{attributeLabel(field)}</span><input required={['username','email'].includes(field)} value={v.claimMapping?.[field]??fallback} onChange={e=>set('claimMapping',{...(v.claimMapping||{}),[field]:e.target.value})}/><code>{field}</code></label>)}</div><div className="notice"><ShieldCheck size={18}/><p>The mapped email or username correlates the SSO subject to one employee. Domain allow-list and account state are checked before a session is created.</p></div></section>}<h3>Default roles for new employees</h3><div className="checkbox-grid">{roles.map((r:any)=><label key={r.id}><input type="checkbox" checked={v.defaultRoles?.includes(r.id)||false} onChange={e=>set('defaultRoles',e.target.checked?[...(v.defaultRoles||[]),r.id]:v.defaultRoles.filter((x:string)=>x!==r.id))}/>{r.name}</label>)}</div><div className="checkbox-row"><label><input type="checkbox" checked={v.enabled!==false} onChange={e=>set('enabled',e.target.checked)}/>Provider enabled</label><label><input type="checkbox" checked={v.jitProvisioning!==false} onChange={e=>set('jitProvisioning',e.target.checked)}/>Create employee on first sign-in</label></div>{provider.id&&v.type==='saml'&&<div className="notice"><BookOpen size={19}/><p>SP metadata: <code>{location.origin}/sso/{provider.id}/metadata</code></p></div>}<div className="form-actions">{remove&&<button type="button" className="text-button danger" onClick={remove}>Delete provider</button>}<button className="primary" disabled={busy||!v.name}><Fingerprint size={16}/>Save SSO provider</button></div></form>}
function AttributePicker({title,description,values,selected,setSelected}:any){const all=selected.length===values.length;return <section className="attribute-picker"><div className="attribute-picker-heading"><div><h3>{title}</h3><p>{description}</p></div><button type="button" className="text-button" onClick={()=>setSelected(all?[]:[...values])}>{all?'Clear all':'Select all'}</button></div><div className="attribute-grid">{values.map((value:string)=><label className={selected.includes(value)?'chosen':''} key={value}><input type="checkbox" checked={selected.includes(value)} onChange={e=>setSelected(e.target.checked?[...selected,value]:selected.filter((x:string)=>x!==value))}/><span>{attributeLabel(value)}</span><code>{value}</code></label>)}</div></section>}
function AttributePolicyForm({client,busy,save}:any){const [read,setRead]=useState(client.readAttributes||readableAttributes),[write,setWrite]=useState(client.writeAttributes||writableAttributes);return <form onSubmit={e=>{e.preventDefault();save({readAttributes:read,writeAttributes:write})}}><div className="notice"><ShieldCheck size={20}/><div><b>{client.name}</b><p>Changes apply immediately to every authentication method and issued token for this client. Resource IDs and protocol metadata remain available so responses can be identified.</p></div></div><AttributePicker title="Readable user attributes" description="Only selected user fields are returned through enabled identity API adapters." values={readableAttributes} selected={read} setSelected={setRead}/><AttributePicker title="Writable user attributes" description="Create, update and lifecycle operations are rejected when they contain an unselected field." values={writableAttributes} selected={write} setSelected={setWrite}/><div className="form-actions"><button className="primary" disabled={busy}><ShieldCheck size={16}/>Save attribute policy</button></div></form>}
function ClientForm({save,busy}:any){const [name,setName]=useState(''),[selected,setSelected]=useState(['users:read','roles:read']),[methods,setMethods]=useState(['oauth2_client_credentials']),[redirectUri,setRedirectUri]=useState(location.origin+'/oauth/callback'),[read,setRead]=useState([...readableAttributes]),[write,setWrite]=useState([...writableAttributes]);return <form onSubmit={e=>{e.preventDefault();save({name,scopes:selected,authenticationMethods:methods,redirectUris:[redirectUri],readAttributes:read,writeAttributes:write})}}><label>Integration name<input required placeholder="e.g. Dechpoint provisioning connector" value={name} onChange={e=>setName(e.target.value)}/></label><h3>Authentication methods</h3><p className="muted">Choose one or more methods this client may use. Credentials are shown once.</p><div className="auth-method-picker">{authMethods.map(([id,label,description])=><label className={methods.includes(id)?'chosen':''} key={id}><input type="checkbox" checked={methods.includes(id)} onChange={e=>setMethods(e.target.checked?[...methods,id]:methods.filter(x=>x!==id))}/><span><b>{label}</b><small>{description}</small></span></label>)}</div>{methods.includes('oauth2_authorization_code_pkce')&&<label>OAuth redirect URI<input required type="url" value={redirectUri} onChange={e=>setRedirectUri(e.target.value)}/></label>}<h3>Allowed scopes</h3><p className="muted">Scopes control operations. Attribute policy below controls the fields within those operations.</p><div className="checkbox-grid">{scopes.map(s=><label key={s}><input type="checkbox" checked={selected.includes(s)} onChange={e=>setSelected(e.target.checked?[...selected,s]:selected.filter(x=>x!==s))}/><code>{s}</code></label>)}</div><AttributePicker title="Readable user attributes" description="Choose the fields this client can retrieve." values={readableAttributes} selected={read} setSelected={setRead}/><AttributePicker title="Writable user attributes" description="Choose the fields this client can create or change." values={writableAttributes} selected={write} setSelected={setWrite}/><div className="form-actions"><button className="primary" disabled={busy||!selected.length||!methods.length}><KeyRound size={16}/>Create client credentials</button></div></form>}
function TokenTester({notify}:any){const [method,setMethod]=useState('oauth2_client_credentials'),[id,setId]=useState(''),[secret,setSecret]=useState(''),[scope,setScope]=useState('users:read'),[result,setResult]=useState<any>(null),[busy,setBusy]=useState(false);const encode=(b:ArrayBuffer)=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');const run=async(e:any)=>{e.preventDefault();setBusy(true);try{if(method==='oauth2_client_credentials'||method==='jwt_bearer'){const r=await fetch(method==='jwt_bearer'?'/oauth/jwt':'/oauth/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({grant_type:'client_credentials',client_id:id,client_secret:secret,scope})});setResult(await r.json())}else if(method==='oauth2_authorization_code_pkce'){const verifier=encode(crypto.getRandomValues(new Uint8Array(48)).buffer),challenge=encode(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier)));const authorize=new URL('/oauth/authorize',location.origin);Object.entries({response_type:'code',client_id:id,redirect_uri:location.origin+'/oauth/callback',code_challenge:challenge,code_challenge_method:'S256',scope,state:crypto.randomUUID()}).forEach(([k,v])=>authorize.searchParams.set(k,v));const approval=await fetch(authorize,{credentials:'same-origin'});const code=await approval.json();if(!code.code)throw Error(code.detail||'Authorization failed');const token=await fetch('/oauth/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({grant_type:'authorization_code',client_id:id,code:code.code,redirect_uri:location.origin+'/oauth/callback',code_verifier:verifier})});setResult(await token.json())}else if(method==='hmac_sha256'){const timestamp=String(Math.floor(Date.now()/1000)),nonce=crypto.randomUUID(),emptyHash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new Uint8Array()))).map(x=>x.toString(16).padStart(2,'0')).join(''),canonical=['GET','/api/v1/users',timestamp,nonce,emptyHash].join('\n'),key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']),signature=Array.from(new Uint8Array(await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(canonical)))).map(x=>x.toString(16).padStart(2,'0')).join('');const r=await fetch('/api/v1/users',{headers:{'X-Client-ID':id,'X-Timestamp':timestamp,'X-Nonce':nonce,'X-Signature':signature},credentials:'omit'});setResult({status:r.status,authentication:'HMAC SHA-256',response:await r.json().catch(()=>({}))})}else if(method==='http_digest'){setResult({authentication:'HTTP Digest',command:`curl --digest -u "${id}:${secret}" http://localhost:8787/api/v1/users`,note:'Digest uses a server challenge and cannot be initiated by browser fetch. Run this generated command to test the real API.'})}else{const headers=method==='api_key'?{'X-API-Key':secret}:{Authorization:'Basic '+btoa(id+':'+secret)};const r=await fetch('/api/v1/users',{headers,credentials:'omit'});const response=await r.json().catch(()=>({}));setResult({status:r.status,authentication:method==='api_key'?'API Key':'HTTP Basic',response})}}catch(e:any){setResult({error:e.message})}finally{setBusy(false)}};const secretLabel=method==='api_key'?'API key':method==='hmac_sha256'?'HMAC signing secret':method==='http_digest'?'Digest password':'Client secret';return <section className="card padded"><div className="section-heading no-pad"><div><h2>Authentication workbench</h2><p>Select any method and exercise the real authentication path.</p></div><KeyRound className="accent" size={24}/></div><form onSubmit={run}><div className="form-grid three"><label>Authentication method<select value={method} onChange={e=>{setMethod(e.target.value);setResult(null);setSecret('')}}>{authMethods.map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label>{method!=='api_key'&&<label>Client ID<input required value={id} onChange={e=>setId(e.target.value)} autoComplete="off"/></label>}{method!=='oauth2_authorization_code_pkce'&&<label>{secretLabel}<input type="password" required value={secret} onChange={e=>setSecret(e.target.value)} autoComplete="off"/></label>}{['oauth2_client_credentials','oauth2_authorization_code_pkce','jwt_bearer'].includes(method)&&<label>Requested scopes<input value={scope} onChange={e=>setScope(e.target.value)}/></label>}</div><button className="button" disabled={busy}><Zap size={15}/>{busy?'Testing…':method.includes('oauth2')||method==='jwt_bearer'?'Authorize and issue token':'Test credentials'}</button></form>{result&&<><pre>{pretty(result)}</pre>{result.access_token&&<button className="button" onClick={()=>navigator.clipboard.writeText(result.access_token).then(()=>notify('Token copied'))}><Copy size={15}/>Copy access token</button>}{result.command&&<button className="button" onClick={()=>navigator.clipboard.writeText(result.command).then(()=>notify('Command copied'))}><Copy size={15}/>Copy test command</button>}</>}</section>}
